// All portfolio content lives here — edit this file to change titles, copy or media.
//
// Videos work in two layers:
//   • `src`   — a short, silent preview loop hosted with the site (plays on the cards).
//   • `watch` — the full video with sound on YouTube or Vimeo (plays in the lightbox).
//               Paste the normal share link, e.g. https://youtu.be/abc123 or https://vimeo.com/123456.
//               Without `watch`, the lightbox plays the preview instead.
//
// Paths are relative to public/. Previews and posters are generated by `npm run media`
// (videos: ../assets/*.mp4 → public/media/<slug>.mp4,
// posters → public/media/posters/<slug>.webp).

export type Category =
  | '3D Motion GFX'
  | 'Video Editing'
  | 'Graphic Design'
  | 'Visual FX'
  | '2D Animation'
  | '3D Full Studio';

export interface Project {
  title: string;
  category: Category;
  /** One line, shown in the hover overlay. */
  description: string;
  /** Preview loop (short, silent). Omit for a still-image project (the poster is shown instead). */
  src?: string;
  /** Full video with sound — a YouTube or Vimeo link. */
  watch?: string;
  /** Poster frame / still image. */
  poster: string;
  /** Portrait (9:16) media instead of landscape (16:9). */
  vertical?: boolean;
}

const video = (slug: string) => ({ src: `media/${slug}.mp4`, poster: `media/posters/${slug}.webp` });

